<template><view class="page"><view class="hero"><text class="eyebrow">B 端开放平台</text><text class="title">把智能命名接入你的产品</text><text class="subtitle">移动端查看账号、套餐额度与调用统计；API Key 请在网页端安全创建和复制。</text></view><view v-if="loading" class="loading">正在读取开放平台…</view><view v-else-if="!account" class="card onboarding"><text class="card-title">开通开发者账号</text><input class="input" v-model="form.company_name" placeholder="公司或团队名称"/><input class="input" v-model="form.contact_name" placeholder="联系人"/><textarea class="input textarea" v-model="form.use_case" placeholder="接入场景和预计用途（至少10字）"/><button class="primary" @click="create">确认开通</button></view><template v-else><view class="card"><text class="card-title">{{account.company_name}}</text><text class="muted">{{account.status==='active'?'账号正常':'账号已暂停'}}</text></view><view class="stats"><view><text>{{summary.calls_total||0}}</text><text>请求总数</text></view><view><text>{{summary.units_total||0}}</text><text>计费单位</text></view><view><text>{{summary.success_total||0}}</text><text>成功</text></view><view><text>{{summary.failed_total||0}}</text><text>失败</text></view></view><text class="section-title">我的套餐</text><view v-if="!subscriptions.length" class="empty card">暂无有效 API 套餐</view><view v-for="item in subscriptions" :key="item.id" class="card"><view class="row between"><text class="card-title">{{item.plan_name}}</text><text class="quota">{{item.quota_remaining}}</text></view><text class="muted">剩余额度 / {{item.quota_total}}</text></view><text class="section-title">可用套餐</text><view v-for="item in plans" :key="item.id" class="card row between"><view><text class="card-title">{{item.name}}</text><text class="muted block">{{item.description}}</text></view><text class="price">{{Number(item.price)===0?'免费':`¥${Number(item.price).toFixed(2)}`}}</text></view></template></view></template>
<script setup>import{reactive,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api,requireLogin}from'../../api';const account=ref(null),plans=ref([]),subscriptions=ref([]),summary=ref({}),loading=ref(true),form=reactive({company_name:'',contact_name:'',use_case:''});async function load(){if(!requireLogin())return;loading.value=true;try{[account.value,plans.value,subscriptions.value,summary.value]=await Promise.all([api.developerAccount(),api.apiPlans(),api.subscriptions(),api.usageSummary()])}catch(e){uni.showToast({title:e.message,icon:'none'})}finally{loading.value=false}}async function create(){if(form.use_case.length<10)return uni.showToast({title:'接入场景至少10字',icon:'none'});try{account.value=await api.createDeveloperAccount(form);uni.showToast({title:'已开通',icon:'success'});load()}catch(e){uni.showToast({title:e.message,icon:'none'})}}onShow(load)</script>
<style scoped>.onboarding{margin-top:28rpx}.onboarding .card-title{display:block;margin-bottom:26rpx}.stats{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;margin-top:20rpx}.stats view{background:#312b26;color:#fff;padding:26rpx;border-radius:18rpx}.stats text{display:block}.stats text:first-child{font-size:40rpx;font-weight:700}.stats text:last-child{color:#cfc5b8;font-size:21rpx}.quota,.price{color:#a94439;font-size:34rpx;font-weight:700}.block{display:block;margin-top:8rpx}</style>
